package com.rootopathy.careos.administration.infrastructure;
import com.rootopathy.careos.administration.application.EvidenceCursorCodec;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
@Component public final class HmacEvidenceCursorCodec implements EvidenceCursorCodec{private static final Base64.Encoder ENCODER=Base64.getUrlEncoder().withoutPadding();private static final Base64.Decoder DECODER=Base64.getUrlDecoder();private final byte[] key;private final Clock clock;public HmacEvidenceCursorCodec(@Value("${careos.security.token-pepper}")String key,Clock clock){this.key=key.getBytes(StandardCharsets.UTF_8);this.clock=clock;}public String encode(Binding b,Position p){var expiry=p.asOf().plusSeconds(900);var payload=String.join("|","1",b.organizationId().toString(),b.projection(),b.filterDigest(),Integer.toString(b.limit()),Long.toString(p.asOf().toEpochMilli()),Long.toString(p.occurredAt().toEpochMilli()),p.id().toString(),Long.toString(expiry.toEpochMilli())).getBytes(StandardCharsets.UTF_8);var signature=sign(payload);var all=Arrays.copyOf(payload,payload.length+signature.length);System.arraycopy(signature,0,all,payload.length,signature.length);return ENCODER.encodeToString(all);}public Position decode(String cursor,Binding b){try{var all=DECODER.decode(cursor);if(all.length<=32)throw invalid();var payload=Arrays.copyOf(all,all.length-32);var signature=Arrays.copyOfRange(all,all.length-32,all.length);if(!MessageDigest.isEqual(signature,sign(payload)))throw invalid();var f=new String(payload,StandardCharsets.UTF_8).split("\\|",-1);if(f.length!=9||!"1".equals(f[0])||!b.organizationId().equals(UUID.fromString(f[1]))||!b.projection().equals(f[2])||!b.filterDigest().equals(f[3])||b.limit()!=Integer.parseInt(f[4]))throw invalid();var asOf=Instant.ofEpochMilli(Long.parseLong(f[5]));var occurred=Instant.ofEpochMilli(Long.parseLong(f[6]));var id=UUID.fromString(f[7]);var expiry=Instant.ofEpochMilli(Long.parseLong(f[8]));if(!expiry.equals(asOf.plusSeconds(900))||clock.instant().isAfter(expiry)||asOf.isAfter(clock.instant().plusSeconds(5)))throw invalid();return new Position(asOf,occurred,id);}catch(RuntimeException e){throw invalid();}}private byte[] sign(byte[] value){try{var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key,"HmacSHA256"));return mac.doFinal(value);}catch(GeneralSecurityException e){throw new IllegalStateException("evidence cursor signing unavailable",e);}}private static IllegalArgumentException invalid(){return new IllegalArgumentException("cursor is invalid, expired, or does not match these filters");}}
